def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (after +)
        if '+' in v:
            version_part, _ = v.split('+', 1)
        else:
            version_part = v

        # Split pre-release (after -)
        if '-' in version_part:
            core_part, prerelease_part = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease_part:
            prerelease_identifiers = prerelease_part.split('.')
            # Convert to comparable tuples
            prerelease_comparable = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    prerelease_comparable.append((0, int(identifier)))
                else:
                    prerelease_comparable.append((1, identifier))
            prerelease_key = (0, tuple(prerelease_comparable))
        else:
            prerelease_key = (1,)  # No pre-release sorts after pre-release

        return (major, minor, patch, prerelease_key)

    # Sort with stable sort (preserves input order for equal elements)
    return sorted(versions, key=parse_version)

